runtime_helper_source:
extends SceneTree
var failures: Array[String] = []
var checks: int = 0
var report_path: String = ""
func _initialize() -> void:
 for arg: String in OS.get_cmdline_user_args():
  if arg.begins_with("--report-path="): report_path=arg.trim_prefix("--report-path=")
 call_deferred("run")
func check(value: bool, label: String) -> void:
 checks+=1
 if not value: failures.append(label)
func run() -> void:
 check(OS.has_feature("mastery_mvp"),"exported MVP feature active")
 check(str(ProjectSettings.get_setting_with_override("application/run/main_scene"))=="res://scenes/mvp/main_mvp.tscn","exported default MVP scene override")
 var assets: Variant=JSON.parse_string(FileAccess.get_file_as_string("res://data/ui/mvp_assets.json"))
 check(assets is Dictionary,"asset catalog JSON")
 if assets is Dictionary:
  for id: String in assets:
   check(load(assets[id]) is Texture2D,"texture "+id)
 check(load("res://assets/fonts/NotoSansKR.ttf") is FontFile,"Korean font")
 for name: String in ["nodes","balance","feature_flags"]:
  check(JSON.parse_string(FileAccess.get_file_as_string("res://data/mastery/"+name+".json")) is Dictionary,"mastery JSON "+name)
 var profile_script=load("res://scripts/mastery_progression.gd")
 var profile=profile_script.new()
 check(profile.definitions.size()==35,"35 definitions in exported profile")
 var scene=load("res://scenes/mvp/main_mvp.tscn")
 check(scene is PackedScene,"MVP main scene")
 var main=scene.instantiate()
 root.add_child(main)
 await process_frame
 check(main.menu!=null and main.board!=null and main.boulder!=null,"MVP runtime ready")
 main.board.refresh(main.mastery,false)
 check(main.board.slots.size()==35,"35 runtime UI slots")
 check(main.menu.controls.size()==6,"6 menu controls")
 var report={"checks":checks,"failures":failures,"resource_root":ProjectSettings.globalize_path("res://"),"scope":"Exported Web PCK executed by native headless Godot from an empty directory; no source-tree fallback. Browser rendering is validated separately.","assets_catalog":assets,"font":"res://assets/fonts/NotoSansKR.ttf"}
 var file=FileAccess.open(report_path,FileAccess.WRITE)
 file.store_string(JSON.stringify(report,"\t"))
 print(JSON.stringify(report))
 main.free()
 await process_frame
 quit(0 if failures.is_empty() else 1)
